import{_ as s,a0 as n,w as a,s as i,ao as d,I as p,x as e,a1 as l,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"USB4 规范获得最终批准，像以太网一样快！ | LCTT x X-CMD","titleTemplate":false,"description":"USB4 规范获得最终批准，像以太网一样快！ | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"USB4 规范获得最终批准，像以太网一样快！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"USB4 规范获得最终批准，像以太网一样快！ | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190905 USB4 gets final approval, offers Ethernet-like speed","title":"USB4 规范获得最终批准，像以太网一样快！","tag":"201909","desc":""},"relativePath":"201909/20190905 USB4 gets final approval, offers Ethernet-like speed.md","filePath":"[post].md"}'),u={name:"201909/20190905 USB4 gets final approval, offers Ethernet-like speed.md"};function S(U,t,B,f,m,T){const r=n("Link");return a(),i("div",null,[t[15]||(t[15]=d('<h1 id="usb4-规范获得最终批准-像以太网一样快" tabindex="-1">USB4 规范获得最终批准，像以太网一样快！ <a class="header-anchor" href="#usb4-规范获得最终批准-像以太网一样快" aria-label="Permalink to “USB4 规范获得最终批准，像以太网一样快！”">​</a></h1><blockquote><p>USB4 会是一个统一的接口，可以淘汰笨重的电缆和超大的插头，并提供满足从笔记本电脑用户到服务器管理员的每个人的吞吐量。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/03/thunderbolt-3_intel-v2-100790083-large.jpg" alt=""></p><p><ruby>USB 开发者论坛<rt>USB Implementers Forum</rt></ruby>（USB-IF）是通用串行总线（USB）规范开发背后的行业协会，上周宣布了它已经完成了下一代 USB4 的技术规范。</p><p>USB4 最重要的一个方面（它们在此版本中省略了首字母缩略词和版本号之间的空格）是它将 USB 与 Intel 设计的接口 Thunderbolt 3 融合在了一起。Thunderbolt 尽管有潜力，但在除了笔记本之外并未真正流行起来。出于这个原因，Intel 向 USB 联盟提供了 Thunderbolt 规范。</p><p>不幸的是，Thunderbolt 3 被列为 USB4 设备的一个可选项，因此有些设备会有，有些则不会。这无疑会让人头疼，希望所有设备制造商都会包括 Thunderbolt 3。</p><p>USB4 将使用与 USB type-C 相同的外形尺寸，这个小型插头用在所有现代 Android 手机和 Thunderbolt 3 中。它将向后兼容 USB 3.2、USB 2.0 以及 Thunderbolt。因此，几乎任何现有的USB type-C 设备都可以连接到具有 USB4 总线的机器，但将以连接电缆的额定速度运行。</p><h3 id="usb4-体积更小-速度更快" tabindex="-1">USB4：体积更小，速度更快 <a class="header-anchor" href="#usb4-体积更小-速度更快" aria-label="Permalink to “USB4：体积更小，速度更快”">​</a></h3><p>因为它支持 Thunderbolt 3，所以这种新连接将同时支持数据和显示协议，因此这可能意味着小型 USB-C 端口将取代显示器上庞大的 DVI 端口，而显示器则带有多个 USB4 端口来作为集线器。</p><p>新标准的主要内容：它提供双通道 40Gbps 传输速度，是当前 USB 3.2 规格的两倍，是 USB 3 的八倍。这是以太网的速度，应该足够给你的高清显示器以及其他数据传输提供充足带宽。</p><p>USB4 也为视频提供了更好的资源分配，因此如果你使用 USB4 端口同时传输视频和数据，端口将相应地分配带宽。这将允许计算机同时使用外部独立的 GPU（因为有 Thunderbolt 3，它已经上市 ）和外部 SSD。</p><p>这可能会启发各种新的服务器设计，因为大型、笨重的设备，如 GPU 或其他不易放入 1U 或 2U 机箱的卡板，现在可以外部连接并以与内部设备相当的速度运行。</p><p>当然，我们看到配备了 USB4 端口的电脑还需要一段时间，更别说服务器了。将 USB 3 用于 PC 花费了数年时间，而 USB-C 的采用速度非常缓慢。USB 2 的 U 盘仍然是这些设备的主要市场，并且主板仍然带有 USB 2 端口。</p><p>尽管如此，USB4 还是有可能成为一个统一的接口，可以摆脱拥有超大插头的笨重电缆，并提供满足从笔记本电脑用户到服务器管理员的每个人的吞吐量。</p><hr>',15)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),l(r,{href:"https://www.networkworld.com/article/3435113/usb4-gets-final-approval-offers-ethernet-like-speed.html"},{default:o(()=>[...t[0]||(t[0]=[e("https://www.networkworld.com/article/3435113/usb4-gets-final-approval-offers-ethernet-like-speed.html",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),l(r,{href:"https://www.networkworld.com/author/Andy-Patrizio/"},{default:o(()=>[...t[2]||(t[2]=[e("Andy Patrizio",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),l(r,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),l(r,{href:"https://github.com/geekpi"},{default:o(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),l(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),l(r,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const C=s(u,[["render",S]]);export{h as __pageData,C as default};
